  private len: number;
  private hd: SingleLink<T> | null;
  private tl: SingleLink<T> | null;

  constructor() {
    this.len = 0;
    this.hd = null;
    this.tl = null;
  }

  // properties getters
  // ...
  // ...

  push(input: T) {
    const link = new SingleLink(input);

    if(this.tl) {
      this.tl.next = link;
      this.tl = link;
    } else {
      this.hd = link;
      this.hd.next = link;
      this.tl = link;
    }

    return ++this.len;
  }


  // methods ...
  // ...
}


Desired Behavior

