int Object3D::triangle_cb(p_ply_argument argument) {
    long length, value_index, propVal;
    void* b_list;
    int val = ply_get_argument_value(argument);
    ply_get_argument_user_data(argument, &b_list, &propVal);
    ply_get_argument_property(argument, NULL, &length, &value_index);
    Triangle* list = (Triangle*) b_list;
    switch (value_index) {
        case -1:
            i_triangle_vert = 0;
            list[i_triangle].nverts = val;
            list[i_triangle].verts = (int*) malloc(val * sizeof(int));
            break;
        case 0:
            list[i_triangle].verts[i_triangle_vert++] = val;
            break;
        case 1:
            list[i_triangle].verts[i_triangle_vert++] = val;
            break;
        case 2:
            list[i_triangle].verts[i_triangle_vert] = val;
            printf("Triangle no:%d, vertices: %d %d %d\n", i_triangle, list[i_triangle].verts[0],list[i_triangle].verts[1],list[i_triangle].verts[2]);
            i_triangle ++;
            break;
    }

    return 1;
}

